@property
def _combined(self) -> IntervalSide:
    import numpy as np
    from pandas.core.dtypes.common import needs_i8_conversion

    left = self.left._values
    right = self.right._values

    # Reshape only if they are ndarray
    if isinstance(left, np.ndarray):
        left = left.reshape(-1, 1)
    if isinstance(right, np.ndarray):
        right = right.reshape(-1, 1)

    if needs_i8_conversion(left.dtype):
        left = np.array(left).reshape(-1, 1)
        right = np.array(right).reshape(-1, 1)
        comb = np.concatenate([left, right], axis=1)
        comb = comb.view("complex128")[:, 0]
    else:
        comb = (np.array(left).ravel().astype("complex128") +
                1j * np.array(right).ravel().astype("complex128"))

    return comb
